web-checks-12.sh:
printf '%s\n' '::ci-local-command-started::'
webhook_ports="$(node --input-type=module -e '
  import { createServer } from "node:net";
  const servers = [createServer(), createServer()];
  await Promise.all(servers.map(server => new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  })));
  console.log(servers.map(server => server.address().port).join(" "));
  await Promise.all(servers.map(server => new Promise(resolve => server.close(resolve))));
')"
read -r webhook_api_port webhook_web_port <<< "$webhook_ports"
WEBHOOK_RUNTIME_API_PORT="$webhook_api_port" WEBHOOK_RUNTIME_PORT="$webhook_web_port" \
  pnpm exec playwright test --config apps/web/src/app/webhooks/webhook-runtime.config.mjs
